node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
const origin='https://dip.vxu.me';
const home=await fetch(origin);assert.equal(home.status,200);assert.match(await home.text(),/The archaeology/);
const dash=await fetch(origin+'/dashboard');assert.equal(dash.status,200);assert.match(await dash.text(),/workspace/);
const session=await fetch(origin+'/api/dashboard');assert.equal(session.status,200);const data=await session.json();assert.equal(data.user,null);
const denied=await fetch(origin+'/api/dashboard',{method:'POST',headers:{origin,'Content-Type':'application/json'},body:JSON.stringify({action:'installations'})});assert.equal(denied.status,401);
console.log(JSON.stringify({landing:home.status,dashboard:dash.status,session:data,unauthenticatedRead:denied.status}));
NODE
